mapper.select:
SELECT COUNT(*) FROM community_post_like relation
JOIN community_post p ON p.id = relation.post_id AND p.status = 'PUBLISHED'
WHERE relation.user_id = #{userId}

SELECT COUNT(*) FROM community_post_favorite relation
JOIN community_post p ON p.id = relation.post_id AND p.status = 'PUBLISHED'
WHERE relation.user_id = #{userId}

mapper.update:
UPDATE community_post
SET title = #{title}, content = #{content}, pet_profile_id = #{petProfileId},
    topic_id = #{topicId}, region = #{region}, latitude = #{latitude}, longitude = #{longitude},
    version = version + 1, updated_at = #{updatedAt}
WHERE id = #{id} AND author_id = #{authorId} AND status != 'DELETED' AND version = #{expectedVersion}

UPDATE community_post
SET status = 'DELETED', version = version + 1, updated_at = #{updatedAt}
WHERE id = #{id} AND author_id = #{authorId} AND status != 'DELETED'

mapper.select:
SELECT 
FROM community_post p
JOIN community_user_follow f ON f.followed_id = p.author_id AND f.follower_id = #{userId}
JOIN app_user u ON u.id = p.author_id
LEFT JOIN pet_profile pet ON pet.id = p.pet_profile_id
LEFT JOIN community_topic t ON t.id = p.topic_id
WHERE p.status = 'PUBLISHED'
AND p.topic_id = #{topicId}
ORDER BY p.published_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM community_post p
JOIN community_user_follow f ON f.followed_id = p.author_id AND f.follower_id = #{userId}
WHERE p.status = 'PUBLISHED'
AND p.topic_id = #{topicId}
